            <div class="etxt-history-group" role="group" aria-label="History & Search">
              <button type="button" class="etxt-tool-icon-btn" id="etxt-find-replace" title="Find in Document (Ctrl+F)" aria-label="Find in Document">${ct.find}</button>
              <button type="button" class="etxt-tool-icon-btn" id="etxt-undo" title="Undo (Ctrl+Z)" aria-label="Undo" ${y.length?"":"disabled"}>${ct.undo}</button>
              <button type="button" class="etxt-tool-icon-btn" id="etxt-redo" title="Redo (Ctrl+Y)" aria-label="Redo" ${$.length?"":"disabled"}>${ct.redo}</button>
            </div>

